def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda v:cnt[v])
    o={v:[(i,j) for i,row in enumerate(g) for j,x in enumerate(row) if x==v] for v in cnt if v!=bg}
    out=[row[:] for row in g]
    def fill(v,p,step):
        r,c=p[0]+step[0],p[1]+step[1]
        while 0<=r<H and 0<=c<W and out[r][c]==bg:
            out[r][c]=v; r+=step[0]; c+=step[1]
    # group colored cells into maximal contiguous diagonal chains per color (4 dirs)
    cells=set([(i,j) for cs in o.values() for i,j in cs])
    used=set()
    for p in sorted(cells):
        if p in used: continue
        # grow along the 4 diagonal directions until blocked
        cur={(p[0],p[1])}; 
