            nxt=set()
            for q in cur:
                for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                    qq=(q[0]+dr,q[1]+dc)
                    if 0<=qq[0]<H and 0<=qq[1]<W and out[qq[0]][qq[1]]!=bg and qq not in cur and qq not in nxt:
                        nxt.add(qq)
            if not nxt: break
            cur.update(nxt)
        # now sort chain by coordinate
        path=sorted(cur)
        for q in path: used.add(q)
        # direction: slope consistent across consecutive pairs
        dirs=[]
        for a,b_ in zip(path,path[1:]):
            dr=abs(b_[0]-a[0]); dc=abs(b_[1]-a[1])
            if dr==dc: dirs.append((1 if b_[0]>a[0] else -1, 1 if b_[1]>a[1] else -1))
        if not dirs or len(path)<2: continue
        dr,dc=dirs[-1]
        st=(dr,dc)
