            cnte=0
            while 0<=r<H and 0<=c<W and out[r][c]==bg:
                out[r][c]=v; cnte+=1; r+=step[0]; c+=step[1]
            if cnte>0: candidates.append(cnte)
        if candidates:
            m=min(candidates)
            # choose candidate that reaches the edge first / fills farthest overall (longest fill)
            cand=None
            bestm=-1
            for e in [path[0],path[-1]]:
                step=(st[0],st[1]) if e is path[-1] else (-st[0],-st[1])
                r=e[0]+step[0]; c=e[1]+step[1]
                dist=0
                while 0<=r<H and 0<=c<W and out[r][c]==bg:
                    dist+=1; r+=step[0]; c+=step[1]
